{{pins}}
int intruders = 0;
int lastMotion = LOW;

void setup() {
  pinMode(PIR_PIN, INPUT);
  pinMode(LED_PIN, OUTPUT);
  pinMode(BUZZER_PIN, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  int motion = digitalRead(PIR_PIN);
  // New movement: quiet last time, motion now.
  if (motion == HIGH && lastMotion == LOW) {
    intruders++;
    Serial.print("Intruder #");
    Serial.println(intruders);
  }
  lastMotion = motion;

  if (motion == HIGH) {
    digitalWrite(LED_PIN, HIGH);
    tone(BUZZER_PIN, 600);
    delay(250);
    digitalWrite(LED_PIN, LOW);
    tone(BUZZER_PIN, 900);
    delay(250);
  } else {
    noTone(BUZZER_PIN);
    digitalWrite(LED_PIN, LOW);
  }
}
